# =============================================================================
# LOOKUP-FUNKTIONER
# =============================================================================

def get_normvärde(kod: str) -> Optional[int]:
    """Hämtar normvärde för given kod."""
    nv = NORMVÄRDEN.get(kod)
    return nv.normvärde if nv else None


def get_normvärde_info(kod: str) -> Optional[Normvärde]:
    """Hämtar all info för given kod."""
    return NORMVÄRDEN.get(kod)


def lookup_by_techspec(
    kategori: str,
    typ_anläggning: str,
    techspec: str,
    volt: str = None,
) -> Optional[Tuple[str, int]]:
    """
    Slår upp normvärde baserat på teknisk specifikation.
    
    Returns:
        Tuple (kod, normvärde) eller None
    """
    for kod, nv in NORMVÄRDEN.items():
        if nv.kategori.lower() != kategori.lower():
            continue
        if nv.typ_anläggning.lower() != typ_anläggning.lower():
            continue
        if nv.techspec.lower() != techspec.lower():
            continue
        if volt and nv.volt != volt:
            continue
        return (kod, nv.normvärde)
    return None


def list_techspecs_for_category(
    kategori: str,
    typ_anläggning: str = None,
) -> List[Tuple[str, str, str, int]]:
    """
    Listar alla techspec-alternativ för en kategori.
    
    Returns:
        Lista med tuples (techspec, volt, kod, normvärde)
    """
    result = []
    for kod, nv in NORMVÄRDEN.items():
        if nv.kategori.lower() != kategori.lower():
            continue
        if typ_anläggning and nv.typ_anläggning.lower() != typ_anläggning.lower():
            continue
        result.append((nv.techspec, nv.volt, kod, nv.normvärde))
    return sorted(result, key=lambda x: (x[0], x[1]))


def list_categories() -> List[str]:
    """Returnerar alla unika kategorier."""
    return sorted(set(nv.kategori for nv in NORMVÄRDEN.values()))


def list_typ_anläggning(kategori: str) -> List[str]:
    """Returnerar alla unika typ_anläggning för given kategori."""
    return sorted(set(
        nv.typ_anläggning for nv in NORMVÄRDEN.values()
        if nv.kategori.lower() == kategori.lower()
    ))


def get_statistics() -> Dict:
    """Returnerar statistik om normvärdeslistan."""
    return {
        "antal_koder": len(NORMVÄRDEN),
        "antal_kategorier": len(list_categories()),
        "kategorier": list_categories(),
        "enheter": {
            "km": sum(1 for nv in NORMVÄRDEN.values() if nv.enhet == "km"),
            "st": sum(1 for nv in NORMVÄRDEN.values() if nv.enhet == "st"),
        },
        "normvärde_min": min(nv.normvärde for nv in NORMVÄRDEN.values()),
        "normvärde_max": max(nv.normvärde for nv in NORMVÄRDEN.values()),
    }
